// The two acceptance sessions finished both zone runs. Their M stores differ
// from a control that never opened the menu, and match each other. This session
// reopens c1's store. The profile byte is read before any mode write. AF-ON
// must apply zone 0, the image default, if the value was not stored.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/accept_reopen_k1.mjs om-emu
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from './zone_session_k1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/accept_reopen_k1.mjs om-emu\n');
  process.exit(2);
}
const OUT = resolve('work/out/accept-reopen-k1.jsonl');
const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify(row));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const ALL = [0x0e, 0x02, 0x02, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];

try {
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-reopen-k1.jsonl',
    tag: 'accept-reopen-k1',
    candidate: true,
    help: true,
    rowLabel: true,
    overlayCsv: 'work/out/overlay-changed-bytes.csv',
    nvramPath: 'work/out/nvram-accept3-c1.json',
    fatalShots: true,
    explanation: 'New session on c1 store. Role: behaviour. The profile byte is RAM.',
    change: 'profile source swap',
    async drive(ctx) {
      const before = ctx.readByte(ctx.PROFILE);
      emit({ record: 'profile-at-boot', profile: before });
      const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
      const api = A(0x50ac4afe);
      ctx.bringUp();
      ctx.s.switch_input('lever', 1);
      ctx.s.camapp.pump();
      ctx.idle(500);
      const argument = ctx.l.call(ctx.native(0x604050e5), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
      ctx.l.call(api, { d0: 289, d1: argument }, null, null, 200000);
      ctx.l.call(api, { d0: 1712, d1: 0 }, null, null, 200000);
      ctx.idle(500);
      const profile = ctx.readByte(ctx.PROFILE);
      emit({ record: 'profile-after-mode', profile, before });
      if (profile !== 0) throw new Error('stored profile came back as ' + profile);
      ctx.key('afon', 'down');
      ctx.idle(600);
      const got = { target: ctx.readTarget(), owner: ctx.readOwn()[4], profile: ctx.readByte(ctx.PROFILE), focus: ctx.s.get(289), subject: ctx.s.get(1712) };
      const pass = same(got.target, ALL) && got.owner === 2 && got.profile === 0 && got.focus === 0 && got.subject === 0;
      emit({ record: 'default-zone', pass, got, expect: { target: ALL, owner: 2, profile: 0 } });
      if (!pass) throw new Error('default zone ' + JSON.stringify(got));
      ctx.key('afon', 'up');
      ctx.idle(300);
    },
  });
  if (!result.ok) throw new Error(result.failed);
  emit({ record: 'done', ok: true });
} catch (e) {
  emit({ record: 'done', ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exitCode = 1;
}
